// Parse and clean the AI Agent output for ElevenLabs TTS

const items = $input.all();
const outputItems = [];

for (const item of items) {
  let text = item.json.output;

  // Remove <speak> and </speak> tags
  text = text.replace(/<speak>/g, '').replace(/<\/speak>/g, '');

  // Remove timestamp markers like [(0:00 - 0:30)]
  text = text.replace(/\[\([0-9:]+\s*-\s*[0-9:]+\)\]/g, '');

  // Remove section headers (lines that are just titles without much content)
  // This regex removes standalone lines that look like headers
  text = text.replace(/\n([A-Z][a-zA-Z\s]+)\n/g, '\n');

  // Clean up multiple newlines
  text = text.replace(/\n{3,}/g, '\n\n');

  // Trim whitespace
  text = text.trim();

  // Escape any quotes for JSON safety
  text = text.replace(/"/g, '\\"');

  outputItems.push({
    json: {
      text: text,
      original_output: item.json.output
    }
  });
}

return outputItems;
